// Generated by InfraKit Visual Editor.
// Mount this at a path of your choosing, e.g.:
//   app.use("/infrakit-access", require("./infrakit-dashboard-login.js"));
//
// Requires in .env: DASHBOARD_ACCESS_KEY, DASHBOARD_ACCESS_PASSWORD (what
// the operator types here), DASHBOARD_USERNAME, DASHBOARD_PASSWORD
// (dashboard's own real login — used internally by the relay below, the
// operator never needs to know these). All four were shown once on your
// export screen.
const PLATFORM_ORIGIN = "http://localhost:4000";
const DASHBOARD_BASE_PATH = "/infrakit";

function renderForm({ error } = {}) {
  return `<!doctype html><html><head><title>Dashboard Access</title>
<style>
  body { font-family: -apple-system, sans-serif; background: #f7f7f8; display: flex;
         align-items: center; justify-content: center; height: 100vh; margin: 0; }
  form { background: white; padding: 32px; border-radius: 12px; width: 300px;
         box-shadow: 0 4px 20px rgba(0,0,0,0.08); }
  h1 { font-size: 16px; margin: 0 0 18px; }
  input { width: 100%; padding: 10px; margin-bottom: 10px; border: 1px solid #ddd;
          border-radius: 6px; box-sizing: border-box; font-size: 14px; }
  button { width: 100%; padding: 10px; border: none; border-radius: 6px; background: #111;
           color: white; font-weight: 600; cursor: pointer; }
  .error { color: #c0392b; font-size: 13px; margin-bottom: 10px; }
</style></head><body>
<form method="POST">
  <h1>Dashboard Access</h1>
  ${error ? `<div class="error">${error}</div>` : ""}
  <input name="accessKey" placeholder="Project Key" required autofocus />
  <input name="password" type="password" placeholder="Password" required />
  <button type="submit">Continue</button>
</form>
</body></html>`;
}

function renderProjectInfo(project) {
  return `<!doctype html><html><head><title>Access Granted</title>
<style>
  body { font-family: -apple-system, sans-serif; background: #f7f7f8; display: flex;
         align-items: center; justify-content: center; height: 100vh; margin: 0; }
  .card { background: white; padding: 32px; border-radius: 12px; width: 320px;
          box-shadow: 0 4px 20px rgba(0,0,0,0.08); }
  h1 { font-size: 16px; margin: 0 0 6px; }
  p { color: #666; font-size: 13px; margin: 4px 0; }
  a { display: block; margin-top: 18px; padding: 10px; border-radius: 6px; background: #111;
      color: white; text-align: center; text-decoration: none; font-weight: 600; font-size: 14px; }
</style></head><body>
<div class="card">
  <h1>${project.name}</h1>
  <p>Provider skin: ${project.provider}</p>
  <p>${project.packageCount} InfraKit package${project.packageCount === 1 ? "" : "s"} configured</p>
  <p>Last updated: ${project.updatedAt}</p>
  <a href="${DASHBOARD_BASE_PATH}/home">Continue to Dashboard →</a>
</div>
</body></html>`;
}

// Dispatches a synthetic request through the SAME app instance — see file
// header for why this is necessary instead of a simpler approach. Forwards
// the real visitor's socket from the original request so dashboard's own
// req.ip-based rate limiting sees the actual caller, not a synthetic one.
function relayDashboardLogin(app, originalReq) {
  return new Promise((resolve) => {
    const EventEmitter = require("events");
    const fakeReq = Object.assign(new EventEmitter(), {
      method: "POST",
      url: `${DASHBOARD_BASE_PATH}/login`,
      headers: { "content-type": "application/x-www-form-urlencoded" },
      body: { username: process.env.DASHBOARD_USERNAME, password: process.env.DASHBOARD_PASSWORD },
      socket: originalReq.socket,
      connection: originalReq.connection,
    });
    let capturedCookie = null;
    const fakeRes = {
      setHeader(name, value) {
        if (name.toLowerCase() === "set-cookie") capturedCookie = value;
      },
      getHeader() {},
      status() { return this; },
      redirect() { resolve(capturedCookie); },
      send() { resolve(capturedCookie); }, // dashboard's login route only ever redirects on success or sends text on failure
      end() { resolve(capturedCookie); },
    };
    app(fakeReq, fakeRes, () => resolve(null));
  });
}

module.exports = function infrakitDashboardLoginRouter(app) {
  const express = require("express");
  const router = express.Router();

  // Manual body parsing, not express.urlencoded() — mirrors
  // @infrakit/dashboard's own approach (its express_urlencoded_fallback),
  // scoped only to the POST route below, not every method — matching how
  // dashboard itself applies it, rather than assuming a specific
  // body-parser setup on the host app.
  function parseFormBody(req, res, next) {
    if (req.body && Object.keys(req.body).length > 0) return next();
    let data = "";
    req.on("data", (chunk) => (data += chunk));
    req.on("end", () => {
      req.body = Object.fromEntries(new URLSearchParams(data).entries());
      next();
    });
  }

  router.get("/", (req, res) => res.send(renderForm()));

  router.post("/", parseFormBody, async (req, res) => {
    const { accessKey, password } = req.body || {};
    if (!accessKey || !password) {
      return res.status(400).send(renderForm({ error: "Both fields are required." }));
    }

    let result;
    try {
      const resp = await fetch(`${PLATFORM_ORIGIN}/auth/verify-credentials`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ accessKey, password }),
      });
      result = await resp.json();
    } catch (err) {
      return res.status(502).send(renderForm({ error: "Could not reach the platform to verify credentials." }));
    }

    if (!result.valid) {
      return res.status(401).send(renderForm({ error: result.error || "Invalid key or password." }));
    }

    // Platform confirmed identity — now complete dashboard's REAL login
    // in-process so the operator gets a genuine, working session.
    const cookie = await relayDashboardLogin(app, req);
    if (!cookie) {
      return res
        .status(500)
        .send(
          renderForm({
            error:
              "Verified with the platform, but couldn't log into the dashboard itself — check DASHBOARD_USERNAME/DASHBOARD_PASSWORD in .env.",
          })
        );
    }

    res.setHeader("Set-Cookie", cookie);
    res.send(renderProjectInfo(result.project));
  });

  return router;
};
